do $iro_controls$
declare
  v_definition text;
  v_constraint text;
  v_function_after text;
  v_constraint_after text;
begin
  select pg_get_functiondef('public.submit_runtime_patient_command(text,text,text,text,bigint,numeric,jsonb)'::regprocedure)
    into v_definition;
  select pg_get_constraintdef(oid) into v_constraint from pg_constraint
    where conrelid='public.runtime_patient_commands'::regclass
      and conname='runtime_patient_commands_command_type_check';
  if encode(extensions.digest(convert_to(v_definition,'UTF8'),'sha256'),'hex') is distinct from
      '8f2bfa76bc8c8b13f2182611fed011ed7846d7f9f3af9d97e986005c2e3350f4'
    or encode(extensions.digest(convert_to(v_constraint,'UTF8'),'sha256'),'hex') is distinct from
      '6013330f3b7a396f648ce4068d7eb1860347bfc1c2846d1f2fc3583c2cba89f0' then
    raise exception 'IRO_SERVER_SOURCE_CAS_MISMATCH' using errcode='55000';
  end if;

  if not exists(select 1 from pg_proc where oid='public.submit_runtime_patient_command(text,text,text,text,bigint,numeric,jsonb)'::regprocedure
    and pg_get_userbyid(proowner)='postgres' and prosecdef
    and proacl::text='{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}'
    and proconfig=array['search_path=""']::text[])
    or not exists(select 1 from pg_class where oid='public.runtime_patient_commands'::regclass
      and pg_get_userbyid(relowner)='postgres' and relrowsecurity and not relforcerowsecurity
      and relacl::text='{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,authenticated=r/postgres}') then
    raise exception 'IRO_SERVER_OWNER_ACL_MISMATCH' using errcode='55000';
  end if;
  if encode(sha256(convert_to(pg_get_functiondef('public.publish_runtime_checkpoint_delta(uuid,text,bigint,jsonb,jsonb)'::regprocedure),'UTF8')),'hex')<>'1f2027be3849144bae8ed1d77c28a506d84ab0f39376bf11cb5e92fc3194c382' then
    raise exception 'IRO_PUBLICATION_PREREQUISITE_MISMATCH' using errcode='55000';
  end if;

  v_function_after:=replace(v_definition,
    $needle$'IRO_RESUME'$needle$,
    $replacement$'IRO_RESUME','IRO_CPR_QUALITY_GOOD','IRO_CPR_QUALITY_POOR','IRO_ROSC_ATTEMPT'$replacement$);
  v_constraint_after:=replace(v_constraint,
    $needle$'IRO_RESUME'::text$needle$,
    $replacement$'IRO_RESUME'::text, 'IRO_CPR_QUALITY_GOOD'::text, 'IRO_CPR_QUALITY_POOR'::text, 'IRO_ROSC_ATTEMPT'::text$replacement$);
  if encode(extensions.digest(convert_to(v_function_after,'UTF8'),'sha256'),'hex')<>
      '3a343f97b580cfd7d2994981076ea696d134fc4bc90746618596c48a19157a5c'
    or encode(extensions.digest(convert_to(v_constraint_after,'UTF8'),'sha256'),'hex')<>
      'a1bb3f0deb7c53498d90c6abe6f84815a56020715ef493d3d1ee4319991af979' then
    raise exception 'IRO_SERVER_REPLACEMENT_SHAPE_MISMATCH' using errcode='55000';
  end if;
  execute v_function_after;
  alter table public.runtime_patient_commands drop constraint runtime_patient_commands_command_type_check;
  execute 'alter table public.runtime_patient_commands add constraint runtime_patient_commands_command_type_check '||v_constraint_after;
  if pg_get_functiondef('public.submit_runtime_patient_command(text,text,text,text,bigint,numeric,jsonb)'::regprocedure)
      is distinct from v_function_after
    or (select pg_get_constraintdef(oid) from pg_constraint
      where conrelid='public.runtime_patient_commands'::regclass
      and conname='runtime_patient_commands_command_type_check') is distinct from v_constraint_after then
    raise exception 'IRO_SERVER_POSTCONDITION_FAILED' using errcode='55000';
  end if;
end $iro_controls$;

DO $historical_v3$
DECLARE actual jsonb;
BEGIN
 SELECT q.snapshot INTO actual FROM (SELECT jsonb_build_object(
 'functions',(SELECT jsonb_agg(jsonb_build_object(
  'signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),
  'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text,
